<!-- 文件作用：文章中心与后台文章列表共用图文行、搜索和原生分页展示，管理状态与公开入口明确区分。 -->
<template><view><view v-if="admin&&!allowed" class="subtle-note">仅平台管理员可以管理文章。</view><template v-else><view class="article-search"><Icon name="search" :size="18"/><input v-model="query" class="article-search-input" placeholder="搜索标题或ID" confirm-type="search" @confirm="load()"/><button class="text-btn" @click="load()">搜索</button><button v-if="admin" class="text-btn" @click="go('/pages/manage/articles/edit')"><Icon name="plusempty" :size="17"/>新建</button></view><view v-if="admin" class="tabs article-filters"><button v-for="item in filters" :key="item.value" class="tab" :class="{active:status===item.value}" @click="status=item.value">{{item.label}}</button></view><view v-if="!rows.length&&loading" class="loading-line">正在读取文章…</view><text v-else-if="!rows.length&&!error" class="subtle-note">暂无文章</text><view v-for="(article,index) in rows" :key="article.id" class="article-list-row" :class="{'article-featured':!admin&&index===0&&!!article.cover_url}" @click="open(article)"><image v-if="article.cover_url" class="article-row-image" :src="assetUrl(article.cover_url)" mode="aspectFill" lazy-load/><view class="article-row-copy"><view class="article-row-heading"><text class="article-row-title">{{article.title}}</text><text v-if="admin" class="pill">{{statusName(article.status)}}</text></view><text v-if="article.summary" class="article-row-summary">{{article.summary}}</text><text class="article-row-date">{{time(admin?article.updated_at:article.published_at)}}</text></view><Icon v-if="admin||index!==0||!article.cover_url" name="arrow" :size="15"/></view><ListLoadState :loading="loading" :has-more="hasMore" :error="error" @retry="retryFailed"/></template></view></template>
<script setup lang="ts">
import Icon from './Icon.vue'
import ListLoadState from './ListLoadState.vue'
import {useArticles} from '../lib/use-articles'
import {assetUrl,go,time} from '../lib/format'
import type {ArticleStatus,ArticleSummary} from '../types/content'
const props=withDefaults(defineProps<{admin?:boolean}>(),{admin:false})
const {rows,query,status,loading,error,hasMore,allowed,load,retryFailed}=useArticles(props.admin)
const filters:Array<{label:string;value:ArticleStatus|''}>=[{label:'全部',value:''},{label:'已发布',value:'published'},{label:'草稿',value:'draft'},{label:'已下架',value:'hidden'}]
/** 管理入口只打开编辑页，公共入口永远不携带草稿权限。 */
function open(article:ArticleSummary):void{go((props.admin?'/pages/manage/articles/edit':'/pages/content/articles/detail')+'?id='+encodeURIComponent(article.id))}
/** 使用已登记状态文案，未知值保持一般文章状态。 */
function statusName(value:ArticleStatus):string{return {draft:'草稿',published:'已发布',hidden:'已下架'}[value]||'文章'}
</script>
<style scoped>
.article-search{display:flex;align-items:center;gap:15.3846rpx;min-width:0;border:1px solid var(--line);border-radius:23.0769rpx;padding:7.6923rpx 19.2308rpx;margin-bottom:30.7692rpx}.article-search-input{flex:1;min-width:0;font-size:25rpx}.article-filters{margin-bottom:23.0769rpx}.article-list-row{display:flex;align-items:center;gap:23.0769rpx;min-width:0;padding:30.7692rpx 0;border-bottom:1px solid var(--line-subtle)}.article-row-image{width:161.5385rpx;height:90.3846rpx;flex-shrink:0;border-radius:13.4615rpx}.article-row-copy{flex:1;min-width:0}.article-row-heading{display:flex;align-items:flex-start;gap:15.3846rpx;min-width:0}.article-row-title{display:-webkit-box;flex:1;min-width:0;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:30.7692rpx;line-height:44.2308rpx;font-weight:650;overflow-wrap:anywhere}.article-row-summary{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;margin-top:13.4615rpx;color:var(--muted);font-size:25rpx;line-height:40.3846rpx;white-space:pre-wrap;overflow-wrap:anywhere}.article-row-date{display:block;margin-top:15.3846rpx;font-size:21.1538rpx;color:var(--muted)}.article-featured{position:relative;display:block;padding:0;overflow:hidden;border:1px solid var(--line);border-radius:23.0769rpx;margin:7.6923rpx 0 23.0769rpx;background:var(--surface)}.article-featured .article-row-image{width:100%;height:384.6154rpx;border-radius:0}.article-featured .article-row-copy{position:relative;padding:23.0769rpx}.article-featured .article-row-title{font-size:34.6154rpx;line-height:46.1538rpx}
</style>
